import{_ as l,c as a,a2 as e,o as t}from"./chunks/framework.Bzjhwp8w.js";const f=JSON.parse('{"title":"部署到 Google Cloud Platform","description":"部署到 Google Cloud Platform","frontmatter":{"title":"部署到 Google Cloud Platform","description":"部署到 Google Cloud Platform","layout":"doc"},"headers":[],"relativePath":"langflow/deployment-gcp.md","filePath":"langflow/deployment-gcp.md"}'),r={name:"langflow/deployment-gcp.md"};function n(d,o,i,c,p,s){return t(),a("div",null,o[0]||(o[0]=[e('<h1 id="部署到-google-cloud-platform" tabindex="-1">部署到 Google Cloud Platform <a class="header-anchor" href="#部署到-google-cloud-platform" aria-label="Permalink to &quot;部署到 Google Cloud Platform&quot;">​</a></h1><p>要使用 Cloud Shell 将 Langflow 部署到 Google Cloud Platform，请使用以下脚本。<br> 该脚本将引导您设置一个基于 Debian 的虚拟机 (VM)，其中包含 Langflow 包、Nginx 及运行 Langflow 开发环境所需的配置信息。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>一个具有创建资源所需权限的 GCP（Google Cloud Platform）帐户</li><li>一个在 GCP 上的项目，您希望在其中部署 Langflow</li></ul><h2 id="部署-langflow-在-gcp" tabindex="-1">部署 Langflow 在 GCP <a class="header-anchor" href="#部署-langflow-在-gcp" aria-label="Permalink to &quot;部署 Langflow 在 GCP&quot;">​</a></h2><ol><li>点击下方启动 Cloud Shell。</li></ol><ol start="2"><li>点击 **Trust repo**。某些 gcloud 命令可能无法在临时的 Cloud Shell 环境中运行。</li><li>点击 **Start** 并按照教程部署 Langflow。</li></ol><h2 id="spot-抢占式实例" tabindex="-1">Spot/抢占式实例 <a class="header-anchor" href="#spot-抢占式实例" aria-label="Permalink to &quot;Spot/抢占式实例&quot;">​</a></h2><p>在运行 <a href="https://cloud.google.com/compute/docs/instances/preemptible" target="_blank" rel="noreferrer">spot（抢占式）实例</a> 时，代码和虚拟机（VM）将与常规实例中保持相同的行为，执行启动脚本来配置环境、安装必要的依赖项并运行 Langflow 应用程序。然而，<strong>由于 spot 实例的特性，如果 Google Cloud 需要回收资源，虚拟机可能会随时被终止</strong>。这使得 spot 实例适合于能够处理意外终止和重启的容错、无状态或可中断的工作负载。</p><h2 id="定价" tabindex="-1">定价 <a class="header-anchor" href="#定价" aria-label="Permalink to &quot;定价&quot;">​</a></h2><p>有关详细信息，请参阅 <a href="https://cloud.google.com/products/calculator?hl=zh-cn" target="_blank" rel="noreferrer">GCP 定价计算器</a>。</p>',11)]))}const u=l(r,[["render",n]]);export{f as __pageData,u as default};
